 if not c: h.append(soup.new_tag('link',rel='canonical',href=cu))
 r=h.find('meta',attrs={'name':'robots'}); content='noindex,follow' if filename=='404.html' else 'index,follow,max-image-preview:large,max-snippet:-1,max-video-preview:-1'
 if r:r['content']=content
 else:h.append(soup.new_tag('meta',attrs={'name':'robots','content':content}))
 if not h.find('link',attrs={'rel':'alternate','hreflang':'zh-Hant-TW'}): h.append(soup.new_tag('link',rel='alternate',hreflang='zh-Hant-TW',href=cu))
 if not h.find('meta',attrs={'property':'og:site_name'}): h.append(soup.new_tag('meta',attrs={'property':'og:site_name','content':'仙加味'}))
 if not h.find('meta',attrs={'name':'twitter:card'}): h.append(soup.new_tag('meta',attrs={'name':'twitter:card','content':'summary_large_image'}))
 if not h.find('link',rel=lambda x:x and 'icon' in x): h.append(soup.new_tag('link',rel='icon',href=f'images/logo.png?v={VERSION}',type='image/png'))

